import React, { useState, useEffect } from 'react';
// Import necessary components from react-router-dom
import { BrowserRouter, Routes, Route, Link, useNavigate, useLocation } from 'react-router-dom';

// Assuming Tailwind CSS is set up in your project
// Assuming Navbar.js, HowToUsePage.js, AboutUsPage.js, ContactUsPage.js, TermsOfServicePage.js, FAQPage.js, DownloadPage.js are in the same directory
import Navbar from './Navbar'; // Import the Navbar component
import HowToUsePage from './HowToUsePage'; // Import the HowToUsePage component
import AboutUsPage from './AboutUsPage'; // Import the AboutUsPage component
import ContactUsPage from './ContactUsPage'; // Import the ContactUsPage component
import TermsOfServicePage from './TermsOfServicePage'; // Import the TermsOfServicePage component
import FAQPage from './FAQPage'; // Import the FAQPage component
import DownloadPage from './DownloadPage'; // Import the DownloadPage component


// Placeholder function to simulate fetching download links and thumbnail
// In a real app, this would make an API call to your backend
const fetchDownloadOptions = async (url) => {
    console.log('Fetching options for:', url);
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1500));

    // Basic URL validation
    if (!url || !url.trim()) {
        throw new Error('Please enter a Facebook video URL.');
    }
    // Simple check if it looks like a Facebook URL (can be improved)
    if (!url.includes('facebook.com')) {
        throw new Error('Please enter a valid Facebook URL.');
    }


    // Simulate success for a specific dummy URL pattern
    if (url.includes('facebook.com/watch/') || url.includes('facebook.com/videos/')) {
        // Simulate successful response with download options AND a thumbnail URL
        // In a real scenario, your backend would return various quality/format options and the thumbnail URL
        return {
            thumbnailUrl: 'https://placehold.co/400x225/E5E7EB/1F2937?text=Video+Thumbnail', // Placeholder thumbnail URL
            options: [
                { quality: 'HD', format: 'MP4', size: 'Approx. 50MB', url: 'https://example.com/dummy-hd-download-link.mp4' }, // Replace with actual download links from backend
                { quality: 'SD', format: 'MP4', size: 'Approx. 20MB', url: 'https://example.com/dummy-sd-download-link.mp4' }, // Replace with actual download links from backend
                // Add more options here if your backend provides them, e.g., MP3
                // { quality: 'Audio', format: 'MP3', size: 'Approx. 5MB', url: 'https://example.com/dummy-audio-link.mp3' },
            ]
        };
    } else {
        // Simulate an error for other URLs
        throw new Error('Could not fetch video from this URL. Please check the URL or try again.');
    }
};


function App() {
    // State to manage the input URL for the homepage downloader
    const [videoUrl, setVideoUrl] = useState('');
    // State to manage dark mode for the entire app
    const [darkMode, setDarkMode] = useState(false);
    // State for loading status on the homepage
    const [isLoading, setIsLoading] = useState(false);
    // State for error messages on the homepage
    const [error, setError] = useState(null);
    // State to store download options specifically for the results page
    const [resultsOptions, setResultsOptions] = useState([]); // Array<{quality, url, format, size}>
    // State to store the thumbnail URL for the results page
    const [resultsThumbnailUrl, setResultsThumbnailUrl] = useState(null); // String | null

    // React Router hooks for navigation and location
    const navigate = useNavigate();
    const location = useLocation();
    const currentPage = location.pathname; // Determine current page based on path

    // Effect to check local storage for dark mode preference on mount
    useEffect(() => {
        const isDarkMode = localStorage.getItem('darkMode') === 'true';
        setDarkMode(isDarkMode);
        // Apply dark mode class to the body or html element
        if (isDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, []); // Empty dependency array means this effect runs only once on mount

    // Function to handle dark mode toggle
    const toggleDarkMode = () => {
        const newDarkMode = !darkMode;
        setDarkMode(newDarkMode);
        // Save preference to local storage
        localStorage.setItem('darkMode', newDarkMode);
        // Apply/remove dark mode class
        if (newDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    };

    // Function to handle input change on the homepage
    const handleInputChange = (event) => {
        setVideoUrl(event.target.value);
        // Clear error when user starts typing again
        if (error) {
            setError(null);
        }
         // Note: Clearing resultsOptions and navigating is now handled after successful fetch
         // or when navigating away via Link components, not just on input change
    };

    // Function to handle download button click on the homepage
    // Fetches data and then navigates to the download results page
    const handleDownloadAndNavigate = async () => {
        setError(null); // Clear previous errors
        setResultsOptions([]); // Clear previous results
        setResultsThumbnailUrl(null); // Clear previous thumbnail
        setIsLoading(true);

        try {
            const result = await fetchDownloadOptions(videoUrl);

            // On success, store options and thumbnail
            setResultsOptions(result.options);
            setResultsThumbnailUrl(result.thumbnailUrl);

            // Navigate to the results page AFTER setting state
            navigate('/download'); // Use the navigate function from react-router-dom

        } catch (err) {
            // On error, stay on the homepage and display the error
            setError(err.message || 'An unexpected error occurred.');
            setResultsOptions([]); // Ensure no stale options are shown
            setResultsThumbnailUrl(null); // Ensure no stale thumbnail is shown
            // No navigation needed on error, stay on home
        } finally {
            setIsLoading(false);
        }
    };


    return (
        // BrowserRouter wraps the entire application content
        // This allows use of hooks like useNavigate and useLocation inside App
        <BrowserRouter>
            {/* Main container applying dark mode class based on state */}
            <div className={`min-h-screen bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-200 flex flex-col items-center transition-colors duration-300`}>

                {/* Navigation Bar - Pass dark mode state and toggle function */}
                {/* Navbar links will use react-router-dom's Link component */}
                {/* Pass currentPage for active state styling */}
                {/* Navbar needs to be updated to use react-router-dom Link */}
                <Navbar
                    darkMode={darkMode}
                    toggleDarkMode={toggleDarkMode}
                    currentPage={currentPage} // Pass current path
                />

                {/* Routes define the main content area */}
                <div className="flex-grow w-full flex justify-center">
                    <Routes>
                        {/* Home Page Route */}
                        <Route
                            path="/"
                            element={
                                // Homepage Content (Downloader Interface)
                                // This is rendered when path is '/'
                                <div className="flex flex-col items-center py-10 px-4 w-full">
                                    {/* Header Section */}
                                    <header className="text-center mb-8 mt-8 px-4">
                                        <h1 className="text-4xl md:text-5xl font-bold text-blue-600 dark:text-blue-400 mb-4">
                                            Facebook Video Downloader
                                        </h1>
                                        <p className="text-xl md:text-2xl text-gray-700 dark:text-gray-300">
                                            Download your favorite Facebook videos easily and for free.
                                        </p>
                                    </header>

                                    {/* Main Download Section */}
                                    <main className="w-full max-w-xl bg-white dark:bg-gray-900 rounded-lg shadow-md dark:shadow-lg p-6 md:p-8 mx-4">
                                        <div className="mb-6">
                                            <label htmlFor="videoUrl" className="block text-lg font-medium text-gray-800 dark:text-gray-200 mb-2">
                                                Paste Facebook Video URL here:
                                            </label>
                                            <input
                                                type="text"
                                                id="videoUrl"
                                                className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300"
                                                placeholder="e.g., https://www.facebook.com/watch/?v=..."
                                                value={videoUrl}
                                                onChange={handleInputChange}
                                                disabled={isLoading} // Disable input while loading
                                            />
                                        </div>

                                        {/* Button calls the function that fetches and navigates */}
                                        <button
                                            onClick={handleDownloadAndNavigate} // Call the combined function
                                            className="w-full bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold py-3 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-colors duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
                                            disabled={isLoading || !videoUrl.trim()} // Disable button if loading or input is empty
                                        >
                                            {isLoading ? (
                                                <>
                                                    {/* Loading Spinner */}
                                                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                                    </svg>
                                                    Processing...
                                                </>
                                            ) : (
                                                'Download Video'
                                            )}
                                        </button>

                                        {/* Error Display - Shown only on homepage if fetch failed */}
                                        {error && (
                                            <div className="mt-4 p-3 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-300 rounded-md text-center">
                                                {error}
                                            </div>
                                        )}

                                         {/* Basic How-To / Disclaimer - Shown initially */}
                                         {!isLoading && !error && resultsOptions.length === 0 && !resultsThumbnailUrl && (
                                            <div className="mt-6 text-center text-gray-500 dark:text-gray-400 text-sm">
                                                <p>Enter the full URL of the Facebook video you want to download.</p>
                                                <p className="mt-2 text-xs">Please ensure you have the necessary permissions to download the video. Downloads are intended for personal offline use only.</p>
                                            </div>
                                        )}
                                    </main>
                                </div>
                            }
                        />

                        {/* Download Results Page Route */}
                         <Route
                            path="/download"
                            element={
                                 // Render DownloadPage, passing fetched results and thumbnail
                                 // Need to handle case where user navigates directly to /download
                                 // without fetching first (resultsOptions/resultsThumbnailUrl would be empty/null)
                                 // The DownloadPage component itself has a fallback for empty data.
                                 <DownloadPage
                                    options={resultsOptions}
                                    thumbnailUrl={resultsThumbnailUrl}
                                    // Pass navigate function or a simple handler for internal links in DownloadPage
                                    // Let's pass a simple handler to navigate back home
                                    onNavLinkClick={() => navigate('/')}
                                 />
                            }
                         />


                        {/* Other Pages Routes */}
                        {/* These components need to be updated to use react-router-dom Link */}
                        <Route path="/how-to-use" element={<HowToUsePage />} />
                        <Route path="/about-us" element={<AboutUsPage />} />
                        <Route path="/contact" element={<ContactUsPage />} />
                        <Route path="/privacy" element={<PrivacyPolicyPage />} />
                        <Route path="/terms" element={<TermsOfServicePage />} />
                        <Route path="/faq" element={<FAQPage />} />

                        {/* Optional: 404 Not Found Page */}
                        {/* <Route path="*" element={<NotFoundPage />} /> */}

                    </Routes>
                </div>


                {/* Footer - Appears on all pages */}
                {/* Footer links will use react-router-dom's Link component */}
                {/* Footer links need to be updated to use react-router-dom Link */}
                <footer className="text-center mt-8 mb-4 text-gray-600 dark:text-gray-400 text-sm">
                    {/* Using react-router-dom Link components */}
                    <Link to="/privacy" className="hover:underline mx-2 text-inherit">Privacy Policy</Link> |
                    <Link to="/terms" className="hover:underline mx-2 text-inherit">Terms of Service</Link> |
                    <Link to="/about-us" className="hover:underline mx-2 text-inherit">About Us</Link> |
                    <Link to="/contact" className="hover:underline mx-2 text-inherit">Contact Us</Link> |
                    <Link to="/faq" className="hover:underline mx-2 text-inherit">FAQ</Link>
                    <p className="mt-1">&copy; {new Date().getFullYear()} Your Site Name. All rights reserved.</p>
                </footer>
            </div>
        </BrowserRouter>
    );
}

export default App;
